class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [1] * (n + 1)
        for i in range(1, n + 1):
            pw[i] = pw[i-1] * 10 % k
        w = []
        for i in range(h):
            if i == n - 1 - i:
                w.append(pw[i])
            else:
                w.append((pw[n-1-i] + pw[i]) % k)
        g = [None] * (h + 1)
        g[h] = [False] * k
        g[h][0] = True
        for i in range(h - 1, -1, -1):
            cur = [False] * k
            for r in range(k):
                for d in range(10):
                    if g[i+1][(r - d * w[i]) % k]:
                        cur[r] = True
                        break
            g[i] = cur
        need = 0
        half = []
        for i in range(h):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (need - d * w[i]) % k
                if g[i+1][nr]:
                    half.append(str(d))
                    need = nr
                    break
        if n % 2:
            return ''.join(half) + ''.join(reversed(half[:-1]))
        return ''.join(half) + ''.join(reversed(half))

