public:
    string largestPalindrome(int n, int k) {
        int h = (n + 1) / 2;
        vector<int> pw(n + 1, 1 % k);
        for (int i = 1; i <= n; i++) pw[i] = pw[i-1] * 10 % k;
        vector<int> w(h);
        for (int i = 0; i < h; i++)
            w[i] = (i == n - 1 - i) ? pw[i] : (pw[n-1-i] + pw[i]) % k;
        vector<vector<bool>> g(h + 1, vector<bool>(k, false));
        g[h][0] = true;
        for (int i = h - 1; i >= 0; i--)
            for (int r = 0; r < k; r++)
                for (int d = 0; d < 10 && !g[i][r]; d++)
                    if (g[i+1][((r - d * w[i]) % k + k) % k]) g[i][r] = true;
        int need = 0;
        string half;
        for (int i = 0; i < h; i++) {
            int lo = (i == 0) ? 1 : 0;
            for (int d = 9; d >= lo; d--) {
                int nr = ((need - d * w[i]) % k + k) % k;
                if (g[i+1][nr]) { half.push_back('0' + d); need = nr; break; }
            }
        }
        string res = half;
        for (int i = (n % 2 ? h - 2 : h - 1); i >= 0; i--) res.push_back(half[i]);
        return res;
    }
};

